export interface SendSmsParams { phone: string; captchaUuid: string; captchaCode: string }

export async function sendAppLoginSms(params: SendSmsParams): Promise<void> {
  await portalRequest<boolean>('portal/appLogin/sms', {
    data: {
      phone: params.phone,
      captchaUuid: params.captchaUuid,
      captchaCode: params.captchaCode,
    },
  })
}

