// Minimal raw RESP Redis client for local e2e seeding/inspection.
// Usage:
//   node redis-cli.mjs GET <key>
//   node redis-cli.mjs SET <key> <value> [ttlSeconds]
//   node redis-cli.mjs DEL <key>
import net from 'node:net'

const HOST = process.env.REDIS_HOST || '192.168.1.110'
const PORT = Number(process.env.REDIS_PORT || 16379)
const PASSWORD = process.env.REDIS_PASSWORD || 'Redis_gqpVKeIEUGia1tQe'
const DB = process.env.REDIS_DB || '0'

function enc(args) {
  let out = `*${args.length}\r\n`
  for (const a of args) {
    const s = String(a)
    out += `$${Buffer.byteLength(s)}\r\n${s}\r\n`
  }
  return out
}

function parse(buf) {
  // very small RESP parser, returns {value, rest}
  const line = buf.indexOf('\r\n')
  if (line < 0) return null
  const type = String.fromCharCode(buf[0])
  const head = buf.slice(1, line).toString()
  const rest = buf.slice(line + 2)
  if (type === '+') return { value: head, rest }
  if (type === '-') return { error: head, rest }
  if (type === ':') return { value: Number(head), rest }
  if (type === '$') {
    const n = Number(head)
    if (n === -1) return { value: null, rest }
    if (rest.length < n + 2) return null
    return { value: rest.slice(0, n).toString(), rest: rest.slice(n + 2) }
  }
  if (type === '*') {
    const n = Number(head)
    if (n === -1) return { value: null, rest }
    const arr = []
    let r = rest
    for (let i = 0; i < n; i++) {
      const p = parse(r)
      if (!p) return null
      arr.push(p.value)
      r = p.rest
    }
    return { value: arr, rest: r }
  }
  return { value: head, rest }
}

const [, , cmd, ...rest] = process.argv
if (!cmd) { console.error('usage: node redis-cli.mjs <GET|SET|DEL> ...'); process.exit(2) }

const sock = net.createConnection({ host: HOST, port: PORT })
let buf = Buffer.alloc(0)
const queue = []
let ready = false

function send(args) { sock.write(enc(args)) }

sock.on('connect', () => {
  if (PASSWORD) send(['AUTH', PASSWORD])
  if (DB && DB !== '0') send(['SELECT', DB])
})
sock.on('data', d => {
  buf = Buffer.concat([buf, d])
  let p
  while ((p = parse(buf))) {
    buf = p.rest
    if (p.error) { console.error('ERR', p.error); cleanup(1) }
    else handle(p.value)
  }
})
sock.on('error', e => { console.error('SOCKERR', e.message); process.exit(1) })

let stage = 0
function handle(v) {
  if (!ready) {
    // responses to AUTH/SELECT
    if (PASSWORD && stage === 0) { stage++; return }
    if (DB && DB !== '0' && stage <= 1) { stage++; }
    ready = true
    runOnce()
    return
  }
  console.log(typeof v === 'string' ? v : JSON.stringify(v))
  cleanup(0)
}

function runOnce() {
  if (cmd.toUpperCase() === 'GET') send(['GET', rest[0]])
  else if (cmd.toUpperCase() === 'DEL') send(['DEL', rest[0]])
  else if (cmd.toUpperCase() === 'SET') {
    if (rest[2] != null) send(['SET', rest[0], rest[1], 'EX', rest[2]])
    else send(['SET', rest[0], rest[1]])
  } else { console.error('unknown cmd', cmd); cleanup(2) }
}

let done = false
function cleanup(code) {
  if (done) return
  done = true
  try { sock.end() } catch {}
  process.exit(code)
}
setTimeout(() => { console.error('TIMEOUT'); cleanup(1) }, 8000)

// Minimal raw RESP Redis client for local e2e seeding/inspection.
// node scripts/redis-cli.mjs GET <key> | SET <key> <val> [ttlSec] | DEL <key>
import net from 'node:net'

const HOST = process.env.REDIS_HOST || '192.168.1.110'
const PORT = Number(process.env.REDIS_PORT || 16379)
const PASSWORD = process.env.REDIS_PASSWORD || 'Redis_gqpVKeIEUGia1tQe'
const DB = process.env.REDIS_DB || '0'

const enc = (a) => `*${a.length}\r\n` + a.map(x => { const s = String(x); return `$${Buffer.byteLength(s)}\r\n${s}\r\n` }).join('')

function parse(buf) {
  if (buf.length < 1) return null
  const nl = buf.indexOf('\r\n')
  if (nl < 0) return null
  const type = String.fromCharCode(buf[0])
  const head = buf.slice(1, nl).toString()
  const rest = buf.slice(nl + 2)
  if (type === '+') return { v: head, rest }
  if (type === '-') return { err: head, rest }
  if (type === ':') return { v: Number(head), rest }
  if (type === '$') {
    const n = Number(head)
    if (n === -1) return { v: null, rest }
    if (rest.length < n + 2) return null
    return { v: rest.slice(0, n).toString(), rest: rest.slice(n + 2) }
  }
  if (type === '*') {
    const n = Number(head); if (n === -1) return { v: null, rest }
    const arr = []; let r = rest
    for (let i = 0; i < n; i++) { const p = parse(r); if (!p) return null; arr.push(p.v); r = p.rest }
    return { v: arr, rest: r }
  }
  return { v: head, rest }
}

const [, , cmd, ...args] = process.argv
if (!cmd) { console.error('usage: GET|SET|DEL'); process.exit(2) }

// Build the pipeline of commands: setup (AUTH/SELECT) + final query; track when final executes.
const setup = []
if (PASSWORD) setup.push(['AUTH', PASSWORD])
if (DB && DB !== '0') setup.push(['SELECT', DB])
const cmdUpper = cmd.toUpperCase()
let finalCmd
if (cmdUpper === 'GET') finalCmd = ['GET', args[0]]
else if (cmdUpper === 'DEL') finalCmd = ['DEL', args[0]]
else if (cmdUpper === 'SET') finalCmd = args[2] != null ? ['SET', args[0], args[1], 'EX', args[2]] : ['SET', args[0], args[1]]
else { console.error('unknown cmd'); process.exit(2) }

const all = [...setup, finalCmd]
const sock = net.createConnection({ host: HOST, port: PORT })
let buf = Buffer.alloc(0), idx = 0, done = false
sock.on('connect', () => sock.write(all.map(enc).join('')))
sock.on('data', d => {
  buf = Buffer.concat([buf, d])
  let p
  while ((p = parse(buf))) {
    buf = p.rest
    idx++
    if (p.err) { console.error('ERR', p.err); return fin(1) }
    if (idx === all.length) { console.log(p.v == null ? 'NULL' : (typeof p.v === 'string' ? p.v : JSON.stringify(p.v))); return fin(0) }
  }
})
sock.on('error', e => { console.error('SOCKERR', e.message); fin(1) })
function fin(code) { if (done) return; done = true; try { sock.end() } catch {}; process.exit(code) }
setTimeout(() => { console.error('TIMEOUT'); fin(1) }, 8000)

