import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.ResultSet;
import java.sql.Statement;

// Apply the branch's pending Liquibase DDL to dev ZHISHU_PORTAL for local e2e (idempotent).
public class ApplyDdl {
    static String URL = "jdbc:dm://dameng.v2.fangchanzonghe.shiqu.suzhou.dev.zhi.com:5236?SCHEMA=ZHISHU_PORTAL";

    public static void main(String[] args) throws Exception {
        try (Connection c = DriverManager.getConnection(URL, "SYSDBA", "DaMeng_qZXhjHBFdEB8kInP");
             Statement s = c.createStatement()) {
            addColumn(s, "T_PORTAL_DATA_MAPPING", "SOURCE_USER_NAME", "VARCHAR2(64)",
                    "子系统侧登录名快照（推送用户时记录，展示用；存量历史行为空）");
            addColumn(s, "T_PORTAL_APPLICATION", "ORDER_NUM", "NUMBER(4) DEFAULT 9999",
                    "显示顺序（越小越靠前；未填默认9999排最后；存量按applicationId顺序回填0..n-1）");
            addColumn(s, "T_PORTAL_APPLICATION", "PROJECT_NAME", "VARCHAR2(100)",
                    "所属项目（自由填写，无字典/主数据）");
            // backfill ORDER_NUM for active rows (idempotent MERGE)
            try {
                s.executeUpdate("MERGE INTO \"ZHISHU_PORTAL\".\"T_PORTAL_APPLICATION\" T " +
                        "USING (SELECT \"APPLICATION_ID\", ROW_NUMBER() OVER (ORDER BY \"APPLICATION_ID\") - 1 AS RN " +
                        "FROM \"ZHISHU_PORTAL\".\"T_PORTAL_APPLICATION\" WHERE \"THE_STATE\"='0') B " +
                        "ON (T.\"APPLICATION_ID\"=B.\"APPLICATION_ID\") " +
                        "WHEN MATCHED THEN UPDATE SET T.\"ORDER_NUM\"=B.RN");
                System.out.println("BACKFILL_ORDER_NUM_OK");
            } catch (Exception e) {
                System.out.println("BACKFILL_SKIP: " + e.getMessage());
            }
            System.out.println("DONE");
        }
    }

    static void addColumn(Statement s, String table, String col, String def, String comment) throws Exception {
        ResultSet rs = s.executeQuery("SELECT COUNT(1) FROM ALL_TAB_COLUMNS WHERE OWNER='ZHISHU_PORTAL' AND TABLE_NAME='" +
                table + "' AND COLUMN_NAME='" + col + "'");
        rs.next();
        int exists = rs.getInt(1);
        rs.close();
        if (exists > 0) { System.out.println("EXISTS " + table + "." + col); return; }
        s.executeUpdate("ALTER TABLE \"ZHISHU_PORTAL\".\"" + table + "\" ADD COLUMN \"" + col + "\" " + def);
        s.executeUpdate("COMMENT ON COLUMN \"ZHISHU_PORTAL\".\"" + table + "\".\"" + col + "\" IS '" + comment + "'");
        System.out.println("ADDED " + table + "." + col);
    }
}

